--
-- Badge state. matthewm holds the retired "Legend" badge as well, which
-- GetBadges will not return -- useful for checking the enabled filter by eye.
--
-- The last two rows are the states added with the progress columns: one badge
-- still being worked towards (EarnedAt NULL, 4 of 10) and one earned then
-- revoked. GetBadges returns neither, so they are the rows to look at when
-- checking that the filter works.
--

ON CONFLICT ("UserUUID", "OrganizationUUID", "BadgeUUID") DO UPDATE SET
    "EarnedAt" = EXCLUDED."EarnedAt",
    "EarnedDescription" = EXCLUDED."EarnedDescription",
    "ProgressGoal" = EXCLUDED."ProgressGoal",
    "ProgressCurrent" = EXCLUDED."ProgressCurrent",
    "RevokedAt" = EXCLUDED."RevokedAt",
    "UpdatedBy" = 'seed';
